const chat = $('Input').first().json;
const row = $input.first().json;
const known = row && row.session_id ? row : {};

// conversation so far + the new message
const message = String(chat.chatInput || "").replace(/\s*\n\s*\n\s*/g, "\n").trim();  // no blank lines inside one message
const transcript = (known.transcript ? known.transcript + "\n\n" : "") + "Person: " + message;
// only the person's own words (used later to check the AI's evidence)
const said = transcript.split("\n\n").filter(t => t.startsWith("Person: ")).map(t => t.slice(8)).join("\n");

const FIELDS = ["problem", "affected", "current_process", "desired_outcome",
                "pain_and_effort", "systems_and_data", "proposed_solution"];
const CATEGORIES = ["Process automation", "Data transfer & integration", "Document processing",
                    "Knowledge & search", "Reporting & analytics", "Internal tool", "Unclear"];
const strings = { type: "object", required: FIELDS,
                  properties: Object.fromEntries(FIELDS.map(f => [f, { type: "string" }])) };

const SYSTEM = `You help "Tomte", the intake assistant of the wyn.link team, turn a colleague's idea into a backlog item.
The input is a conversation between a colleague ("Person") and Tomte. Use only what the Person says.
Fill a field ONLY if the Person actually said it. Otherwise return "". Never invent anything.
- problem: what goes wrong today (not a solution)
- affected: roles or teams with the problem ("we" alone does not count)
- current_process: how the work is actually done today ("manual" alone does not count)
- desired_outcome: what concretely should be different ("better" or "automate it" alone does not count)
- pain_and_effort: time, errors, frequency
- systems_and_data: systems, files, documents
- proposed_solution: a solution the Person asks for, e.g. "an AI agent"
evidence: for every field you fill, copy the Person's exact words that support it. No quote, no field.
title: neutral topic name, max 8 words. category: one of ${CATEGORIES.join(", ")}.
Example: "Can you build an AI agent for invoices?" -> proposed_solution: "An AI agent for invoices", evidence: "build an AI agent for invoices", problem: "" (no problem described yet).
`;

const payload = {
  model: "llama3.1",
  stream: false,
  options: { temperature: 0 },
  format: { type: "object", required: ["title", "category", "details", "evidence"],
            properties: { title: { type: "string" }, category: { type: "string", enum: CATEGORIES },
                          details: strings, evidence: strings } },
  messages: [{ role: "system", content: SYSTEM }, { role: "user", content: transcript }],
};

return [{ json: { session_id: chat.sessionId, known, transcript, said, payload } }];

const prev = $('Transcript').first().json;
const known = prev.known;

// read the AI answer safely - if it's broken, we just know nothing new
let ai = {};
try { ai = JSON.parse($input.first().json.message.content); } catch (e) { ai = {}; }

const MUST = ["problem", "affected", "current_process", "desired_outcome"];
const OPTIONAL = ["pain_and_effort", "systems_and_data", "proposed_solution"];
const LABELS = { problem: "the problem", affected: "who is affected",
                 current_process: "how it works today", desired_outcome: "the desired outcome" };
const QUESTIONS = {
  problem: "What exactly goes wrong, takes too long or is annoying today?",
  affected: "Who is affected (role or team), and roughly how many people?",
  current_process: "How is it done today, step by step?",
  desired_outcome: "What should be better once this is solved? How would you notice?",
};
const MAX_QUESTIONS = 3;
const MAX_ROUNDS = 2;

// evidence check: the AI's quote must really come from the person's words
const words = s => (String(s || "").toLowerCase().match(/[\p{L}\p{N}]+/gu) || []);
const quoted = (quote, source) => {
  const w = words(quote).filter(x => x.length > 2);
  const have = new Set(words(source));
  return w.length >= 2 && w.every(x => have.has(x));
};
const filled = v => String(v || "").trim().length >= 5;

// merge: new AI value only if backed by a quote, otherwise keep what we knew
const fields = {};
for (const f of [...MUST, ...OPTIONAL]) {
  const value = ai.details?.[f];
  const related = words(value).some(w => w.length > 3 && words(ai.evidence?.[f]).includes(w));
  fields[f] = filled(value) && quoted(ai.evidence?.[f], prev.said) && related ? value.trim() : (known[f] || "");}

// decide Tomte's reply
const missing = MUST.filter(f => !filled(fields[f]));
let rounds = Number(known.rounds || 0);
let status, reply;
if (missing.length === 0) {
  status = "ready_for_triage";
  reply = "Thanks, that's everything I need. Your idea is ready for the wyn.link team.";
} else if (rounds >= MAX_ROUNDS) {
  status = "needs_info";
  reply = "Thanks, I've passed your idea on. The wyn.link team may come back to you about: "
        + missing.map(f => LABELS[f]).join(", ") + ".";
} else {
  rounds += 1;
  status = "awaiting_details";
  const questions = missing.slice(0, MAX_QUESTIONS).map((f, i) => `${i + 1}. ${QUESTIONS[f]}`).join("\n");
  reply = (rounds === 1 ? "Thanks! A few quick questions so the wyn.link team understands it:"
                        : "Thanks, that helps. Almost done:") + "\n" + questions;
}

return [{ json: {
  session_id: prev.session_id,
  title: ai.title || known.title || "",
  category: ai.category || known.category || "Unclear",
  status, rounds, ...fields,
  missing: missing.join(", "),
  reply,
  transcript: prev.transcript + "\n\nTomte: " + reply,
} }];

const c = $input.first().json;
return [{ json: { sessionId: c.sessionId, chatInput: c.chatInput,
                  channel: "chat", sender: "chat user", subject: "" } }];

const m = $input.first().json;
const sender = (String(m.from || "").match(/[\w.+-]+@[\w.-]+\.\w+/) || ["unknown"])[0].toLowerCase();
// one conversation = same sender + same subject (without Re:/AW:)
const subject = String(m.subject || "").replace(/^\s*((re|aw|fwd|wg)\s*:\s*)+/i, "").trim();

// the email text: plain version, or the HTML version without tags
const raw = m.textPlain || m.text || String(m.textHtml || "")
  .replace(/<br\s*\/?>/gi, "\n").replace(/<\/(div|p)>/gi, "\n")
  .replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ");

// keep only the new text of a reply, drop the quoted earlier mail
const body = String(raw)
  .split(/\n\s*(?:On [\s\S]{0,200}?wrote:|Am [\s\S]{0,200}?schrieb[\s\S]{0,60}?:)/)[0]
  .split("\n").filter(line => !line.startsWith(">")).join("\n").trim();

return [{ json: { sessionId: `${sender}|${subject.toLowerCase()}`, chatInput: body,
                  channel: "email", sender, subject } }];
